extends SceneTree
const Snapshot=preload("res://scripts/progression/run_snapshot.gd")
const State=preload("res://scripts/combat/run_state.gd")
const Campaign=preload("res://tests/test_campaign.gd")
var errors:Array=[]
func expect(ok:bool,label:String):
 if not ok:errors.append(label)
func _initialize():call_deferred("run")
func run():
 var folder:="res://.local_validation/GAME054/cold"
 DirAccess.make_dir_recursive_absolute(folder)
 for name in ["battle.save","gold.cfg","settings.cfg"]:DirAccess.remove_absolute(folder.path_join(name))
 expect(DirAccess.copy_absolute("res://.local_validation/GAME054/render-live/healing.save",folder.path_join("battle.save"))==OK,"copy actual healing reaction save")
 var ui=load("res://scenes/main.tscn").instantiate()
 ui.run_store.path=folder.path_join("battle.save");ui.gold_progress.path=folder.path_join("gold.cfg");ui.settings_path=folder.path_join("settings.cfg")
 root.content_scale_mode=Window.CONTENT_SCALE_MODE_DISABLED;root.content_scale_size=Vector2i(1280,720);root.size=Vector2i(1280,720)
 ui.safe_area_override=Rect2(0,6,1280,702)
 root.add_child(ui);ui.set_physics_process(false);await process_frame;ui._apply_layout()
 expect(ui.battle_save_error==OK and not ui.run_store.pending.is_empty(),"same schema22 atomic reader")
 var saved:Dictionary=ui.run_store.pending.duplicate(true)
 if saved.is_empty():quit(2);return
 ui.start_button.pressed.emit()
 var s=ui.simulation
 expect(s.phase==State.Phase.PAUSED and ui.feedback_panel.expression_key=="normal" and s.feedback.clocks.heal==0,"restored run requires Continue and never replays old HP consumption")
 var ref=State.new();expect(Snapshot.restore(saved,ref),"restore comparison reference")
 ref.set_paused(false);ui.resume_button.pressed.emit()
 var same:=true;var running:=0
 for i in range(100):
  while s.phase==State.Phase.CHOOSING:
   var id:String=s.growth.offer[0];ui._choose_skill(id,s.growth.ticket);ref.select_skill(id,ref.growth.ticket)
  if s.phase==State.Phase.RUNNING:running+=1
  ui._physics_process(.05);ref.step(.05,Vector2.ZERO)
  same=same and Campaign.comparable(s)==Campaign.comparable(ref)
  await process_frame
 expect(same and running==100,"all100running authority and seven RNG comparisons match")
 expect(s.hp==saved.run.hp and s.feedback.clocks.heal==0,"no repeated item healing or expression on resume")
 var result:Dictionary={"status":"PASS" if errors.is_empty() else "FAIL","errors":errors,"steps":100,"running":running,"authority_equal":same,"hp":s.hp,"saved_hp":saved.run.hp,"expression":ui.feedback_panel.expression_key,"schema":Snapshot.VERSION}
 var f=FileAccess.open(folder.path_join("report.json"),FileAccess.WRITE);f.store_string(JSON.stringify(result,"  "));f.close();print(JSON.stringify(result));ui.combat_audio.stop_all();await create_timer(.06).timeout;ui.queue_free();await process_frame;await create_timer(.1).timeout;quit(0 if errors.is_empty() else 1)
